    # This function uses the bisection method to find a root of the polynomial
    # defined by the coefficients in xs.
    # The bisection method requires an interval [a, b] where the function
    # changes sign, i.e., poly(a) * poly(b) < 0.
    # We start with an interval [-10, 10] and refine it until we find a root.

    def bisection_method(a, b, tol=1e-7):
        if poly(xs, a) * poly(xs, b) >= 0:
            raise ValueError("Bisection method requires that poly(a) and poly(b) have opposite signs.")

        while (b - a) / 2.0 > tol:
            midpoint = (a + b) / 2.0
            if poly(xs, midpoint) == 0:
                return midpoint
            elif poly(xs, a) * poly(xs, midpoint) < 0:
                b = midpoint
            else:
                a = midpoint
        return (a + b) / 2.0

    # Start with an interval [-10, 10]
    return bisection_method(-10, 10)
