def encrypt(s):
    def shift_char(c):
        if 'a' <= c <= 'z':
            # Rotate within lowercase letters
            return chr((ord(c) - ord('a') + 4) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            # Rotate within uppercase letters
            return chr((ord(c) - ord('A') + 4) % 26 + ord('A'))
        else:
            # Non-alphabetic characters remain unchanged
            return c

    # Apply the shift to each character in the string
    return ''.join(shift_char(c) for c in s)

