    """
    Encode a message by swapping the case of all letters and replacing
    all vowels with the letter that appears 2 places ahead of that vowel
    in the English alphabet. Assume only letters.
    """
    def shift_vowel(vowel):
        vowels = 'aeiouAEIOU'
        shifted = {
            'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
            'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
        }
