def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False

    # Check if the date format is mm-dd-yyyy
    if len(date) != 10 or date[2] != '-' or date[5] != '-':
        return False

    # Extract month, day, and year
    try:
        month = int(date[:2])
        day = int(date[3:5])
        year = int(date[6:])
    except ValueError:
        return False

    # Validate the month
    if month < 1 or month > 12:
        return False

    # Validate the day based on the month
    if month in {1, 3, 5, 7, 8, 10, 12}:
        if day < 1 or day > 31:
            return False
    elif month in {4, 6, 9, 11}:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        # Check for leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            if day < 1 or day > 29:
                return False
        else:
            if day < 1 or day > 28:
                return False

    # If all checks pass, the date is valid
    return True

